import { test, expect } from '@playwright/test';

test.describe('Drawer/Slide-in Panel from Right', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/drawer-panel');
  });

  test('should open drawer panel from right when button is clicked', async ({ page }) => {
    // Verify drawer is initially closed
    const drawer = page.getByRole('region', { name: /drawer panel/i });
    await expect(drawer).not.toBeVisible();

    // Click the open button using getByRole
    const openButton = page.getByRole('button', { name: /open drawer/i });
    await expect(openButton).toBeVisible();
    await openButton.click();

    // Verify drawer is now visible
    await expect(drawer).toBeVisible();

    // Verify drawer has correct width and position
    const drawerBoundingBox = await drawer.boundingBox();
    expect(drawerBoundingBox.width).toBeGreaterThan(300);
    expect(drawerBoundingBox.x).toBeGreaterThan(page.viewportSize().width - 500);

    // Verify drawer content is visible
    const drawerTitle = page.getByText(/drawer panel/i);
    await expect(drawerTitle).toBeVisible();

    // Verify close button is visible and clickable
    const closeButton = page.getByRole('button', { name: /close drawer/i });
    await expect(closeButton).toBeVisible();
    await expect(closeButton).not.toBeDisabled();

    // Verify drawer is positioned on the right side
    const drawerRightEdge = await drawer.evaluate((el) => el.getBoundingClientRect().right);
    const viewportRightEdge = page.viewportSize().width;
    expect(drawerRightEdge).toBeCloseTo(viewportRightEdge);
  });

  test('should close drawer panel when close button is clicked or ESC is pressed', async ({ page }) => {
    // Open the drawer panel
    const openButton = page.getByRole('button', { name: /open drawer/i });
    await openButton.click();

    const drawer = page.getByRole('region', { name: /drawer panel/i });
    await expect(drawer).toBeVisible();

    // Close the drawer using the close button
    const closeButton = page.getByRole('button', { name: /close drawer/i });
    await closeButton.click();

    // Verify drawer is closed
    await expect(drawer).not.toBeVisible();

    // Verify open button is still visible and functional
    await expect(openButton).toBeVisible();

    // Close the drawer using ESC key
    await page.keyboard.press('Escape');
    await expect(drawer).not.toBeVisible();

    // Verify drawer is not visible after ESC
    const drawerBoundingBox = await drawer.boundingBox();
    expect(drawerBoundingBox).toBeNull();
  });
});
